#!/usr/bin/env python3
"""Run packed synthetic planning factors with hard supervision and status audits."""

# Some portions generated by Codex

from __future__ import annotations

import argparse
import hashlib
import json
import math
import pathlib
import subprocess
import sys
from collections.abc import Sequence
from typing import Any


FACTORS = (4, 8, 16, 17, 32, 64, 65, 128)
BENCHMARK = (
    "org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed."
    "PackedCascadesSearchBenchmark.plan"
)
FOUR_FACTOR_TIME_MILLIS = 0.5
FOUR_FACTOR_ALLOCATION_BYTES = 512 * 1024
EIGHT_FACTOR_TIME_MILLIS = 5.0
EIGHT_FACTOR_ALLOCATION_BYTES = 2 * 1024 * 1024
DEFAULT_SATURATED_WARMUP_ITERATIONS = 20
COLD_LANE = "cold"
SATURATED_LANE = "saturated"


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument("--jar", type=pathlib.Path, required=True)
    parser.add_argument("--results", type=pathlib.Path, required=True)
    parser.add_argument("--summary", type=pathlib.Path, required=True)
    parser.add_argument("--timeout-seconds", type=float, default=75.0)
    parser.add_argument("--termination-grace-seconds", type=float, default=5.0)
    parser.add_argument("--measurements", type=int, default=7)
    parser.add_argument(
        "--warmup-iterations",
        type=int,
        default=DEFAULT_SATURATED_WARMUP_ITERATIONS,
    )
    parser.add_argument("--resume", action="store_true")
    parser.add_argument("--audit-only", action="store_true")
    parser.add_argument("--factor", action="append", type=int)
    args = parser.parse_args()
    if (
        args.timeout_seconds <= 0
        or args.termination_grace_seconds < 0
        or args.measurements <= 1
        or args.warmup_iterations <= 0
    ):
        parser.error(
            "positive timeout and warmups, non-negative grace, and at least two measurements are required"
        )
    if args.factor and any(factor <= 0 for factor in args.factor):
        parser.error("factors must be positive")
    if not args.jar.is_file():
        parser.error(f"benchmark jar does not exist: {args.jar}")
    return args


def digest(path: pathlib.Path) -> str | None:
    if not path.is_file():
        return None
    value = hashlib.sha256()
    with path.open("rb") as source:
        for block in iter(lambda: source.read(1024 * 1024), b""):
            value.update(block)
    return value.hexdigest()


def read_json(path: pathlib.Path) -> Any:
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return None


def write_json(path: pathlib.Path, value: object) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(path.name + ".tmp")
    temporary.write_text(json.dumps(value, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    temporary.replace(path)


def status_path(result: pathlib.Path) -> pathlib.Path:
    return result.with_suffix(".status.json")


def stdout_path(result: pathlib.Path) -> pathlib.Path:
    return result.with_suffix(".stdout.log")


def stderr_path(result: pathlib.Path) -> pathlib.Path:
    return result.with_suffix(".stderr.log")


def audit_path(results: pathlib.Path, factor: int) -> pathlib.Path:
    return results / f"factor-{factor}.audit.json"


def jmh_path(results: pathlib.Path, factor: int, lane: str) -> pathlib.Path:
    if lane not in {COLD_LANE, SATURATED_LANE}:
        raise ValueError(f"unsupported timing lane: {lane}")
    return results / f"factor-{factor}.{lane}.jmh.json"


def outcome(result: pathlib.Path) -> str | None:
    status = read_json(status_path(result))
    return status.get("outcome") if isinstance(status, dict) else None


def completed_audit(result: pathlib.Path, factor: int) -> bool:
    value = read_json(result)
    return (
        outcome(result) == "succeeded"
        and isinstance(value, dict)
        and value.get("kind") == "packed-cascades-search-audit"
        and value.get("factors") == factor
        and isinstance(value.get("completionStatus"), str)
        and isinstance(value.get("exact"), bool)
    )


def jmh_entry(
    result: pathlib.Path,
    factor: int,
    warmup_iterations: int,
    measurement_iterations: int,
) -> dict[str, Any] | None:
    value = read_json(result)
    if outcome(result) != "succeeded" or not isinstance(value, list) or len(value) != 1:
        return None
    entry = value[0]
    if (
        not isinstance(entry, dict)
        or entry.get("benchmark") != BENCHMARK
        or entry.get("mode") != "ss"
        or entry.get("threads") != 1
        or entry.get("forks") != 1
        or entry.get("warmupIterations") != warmup_iterations
        or entry.get("measurementIterations") != measurement_iterations
        or entry.get("params") != {"factors": str(factor)}
    ):
        return None
    return entry


def issue(result: pathlib.Path, valid: bool, lane: str) -> str | None:
    result_outcome = outcome(result)
    if result_outcome in {"timeout", "failed"}:
        return f"{lane}-{result_outcome}"
    if result_outcome is None and not result.exists():
        return f"{lane}-missing"
    if not valid:
        return f"{lane}-stale"
    return None


def raw_samples(metric: dict[str, Any]) -> list[float]:
    raw = metric.get("rawData")
    if not isinstance(raw, list):
        raise ValueError("JMH metric has no rawData")
    samples: list[float] = []
    for fork in raw:
        if not isinstance(fork, list):
            raise ValueError("JMH rawData fork is not a list")
        for sample in fork:
            if not isinstance(sample, (int, float)) or not math.isfinite(sample) or sample < 0:
                raise ValueError("JMH rawData contains an invalid sample")
            samples.append(float(sample))
    if not samples:
        raise ValueError("JMH metric has no samples")
    return samples


def percentile_nearest_rank(values: Sequence[float], percentile: float) -> float:
    ordered = sorted(values)
    if not ordered:
        raise ValueError("percentile requires samples")
    rank = max(1, math.ceil(percentile * len(ordered)))
    return ordered[rank - 1]


def measurement_samples(entry: dict[str, Any]) -> tuple[list[float], list[float]]:
    primary = entry.get("primaryMetric")
    secondary = entry.get("secondaryMetrics")
    if not isinstance(primary, dict) or not isinstance(secondary, dict):
        raise ValueError("JMH entry lacks primary or secondary metrics")
    allocation_metric = secondary.get("gc.alloc.rate.norm")
    if not isinstance(allocation_metric, dict):
        raise ValueError("JMH entry lacks normalized allocation")
    times = raw_samples(primary)
    allocations = raw_samples(allocation_metric)
    if len(times) != len(allocations):
        raise ValueError("time and allocation sample counts differ")
    return times, allocations


def cold_measurement(entry: dict[str, Any]) -> dict[str, Any]:
    cold_times, cold_allocations = measurement_samples(entry)
    if len(cold_times) != 1:
        raise ValueError("process-cold lane must contain exactly one sample")
    return {
        "coldSampleCount": len(cold_times),
        "coldMillis": cold_times[0],
        "coldAllocationBytes": cold_allocations[0],
        "coldRawMillis": cold_times,
        "coldRawAllocationBytes": cold_allocations,
    }


def saturated_measurement(entry: dict[str, Any]) -> dict[str, Any]:
    saturated_times, saturated_allocations = measurement_samples(entry)
    saturated_p95_millis = percentile_nearest_rank(saturated_times, 0.95)
    saturated_p95_allocation = percentile_nearest_rank(saturated_allocations, 0.95)
    return {
        "saturatedSampleCount": len(saturated_times),
        "saturatedP95Millis": saturated_p95_millis,
        "saturatedP95AllocationBytes": saturated_p95_allocation,
        "saturatedRawMillis": saturated_times,
        "saturatedRawAllocationBytes": saturated_allocations,
    }


def factor_measurement(
    audit: dict[str, Any],
    cold: dict[str, Any],
    saturated: dict[str, Any],
    factor: int,
) -> dict[str, Any]:
    all_times = cold["coldRawMillis"] + saturated["saturatedRawMillis"]
    all_allocations = (
        cold["coldRawAllocationBytes"] + saturated["saturatedRawAllocationBytes"]
    )
    return {
        "factors": factor,
        "status": "complete",
        "issues": [],
        "completionStatus": audit["completionStatus"],
        "exact": audit["exact"],
        "retainedBytes": audit.get("retainedBytes"),
        "sampleCount": len(all_times),
        **cold,
        **saturated,
        "allSampleP95Millis": max(
            cold["coldMillis"], saturated["saturatedP95Millis"]
        ),
        "allSampleP95AllocationBytes": max(
            cold["coldAllocationBytes"],
            saturated["saturatedP95AllocationBytes"],
        ),
        "rawMillis": all_times,
        "rawAllocationBytes": all_allocations,
    }


def gate(
    record: dict[str, Any] | None,
    time_limit: float,
    allocation_limit: int,
    lane: str,
) -> bool:
    if record is None or record.get("status") != "complete":
        return False
    if lane == COLD_LANE:
        return (
            record["coldMillis"] <= time_limit
            and record["coldAllocationBytes"] <= allocation_limit
        )
    if lane == SATURATED_LANE:
        prefix = "saturated"
    elif lane == "allSample":
        prefix = "allSample"
    else:
        raise ValueError(f"unsupported gate lane: {lane}")
    return (
        record[f"{prefix}P95Millis"] <= time_limit
        and record[f"{prefix}P95AllocationBytes"] <= allocation_limit
    )


def summarize_campaign(
    results: pathlib.Path,
    factors: Sequence[int],
    measurements: int,
    warmup_iterations: int = DEFAULT_SATURATED_WARMUP_ITERATIONS,
) -> dict[str, Any]:
    records: list[dict[str, Any]] = []
    exact: list[int] = []
    incomplete: list[int] = []
    for factor in factors:
        audit_result = audit_path(results, factor)
        cold_result = jmh_path(results, factor, COLD_LANE)
        saturated_result = jmh_path(results, factor, SATURATED_LANE)
        audit_valid = completed_audit(audit_result, factor)
        cold_entry = jmh_entry(cold_result, factor, 0, 1)
        saturated_entry = jmh_entry(
            saturated_result,
            factor,
            warmup_iterations,
            measurements,
        )
        issues = [
            value
            for value in (
                issue(audit_result, audit_valid, "audit"),
                issue(cold_result, cold_entry is not None, "cold-jmh"),
                issue(
                    saturated_result,
                    saturated_entry is not None,
                    "saturated-jmh",
                ),
            )
            if value is not None
        ]
        audit_value = read_json(audit_result) if audit_valid else None
        audit = audit_value if isinstance(audit_value, dict) else None
        record: dict[str, Any] = {
            "factors": factor,
            "status": "incomplete",
            "issues": issues,
            "completionStatus": audit.get("completionStatus") if audit else None,
            "exact": audit.get("exact") if audit else None,
            "retainedBytes": audit.get("retainedBytes") if audit else None,
        }
        if audit is not None:
            (exact if audit["exact"] else incomplete).append(factor)
        cold = None
        if cold_entry is not None:
            try:
                cold = cold_measurement(cold_entry)
                record.update(cold)
            except ValueError as failure:
                issues.append(f"cold-jmh-invalid:{failure}")
        saturated = None
        if saturated_entry is not None:
            try:
                saturated = saturated_measurement(saturated_entry)
                record.update(saturated)
            except ValueError as failure:
                issues.append(f"saturated-jmh-invalid:{failure}")
        if issues:
            records.append(record)
            continue
        assert audit is not None and cold is not None and saturated is not None
        record = factor_measurement(audit, cold, saturated, factor)
        records.append(record)
    by_factor = {record["factors"]: record for record in records}
    complete_count = sum(record["status"] == "complete" for record in records)
    return {
        "formatVersion": 2,
        "status": "complete" if complete_count == len(factors) and factors else "incomplete",
        "expectedFactorCount": len(factors),
        "completedFactorCount": complete_count,
        "exactFactors": exact,
        "incompleteFactors": incomplete,
        "fourFactorColdGatePass": gate(
            by_factor.get(4), FOUR_FACTOR_TIME_MILLIS, FOUR_FACTOR_ALLOCATION_BYTES, COLD_LANE
        ),
        "fourFactorAllSampleGatePass": gate(
            by_factor.get(4), FOUR_FACTOR_TIME_MILLIS, FOUR_FACTOR_ALLOCATION_BYTES, "allSample"
        ),
        "fourFactorSaturatedGatePass": gate(
            by_factor.get(4), FOUR_FACTOR_TIME_MILLIS, FOUR_FACTOR_ALLOCATION_BYTES, SATURATED_LANE
        ),
        "eightFactorColdGatePass": gate(
            by_factor.get(8), EIGHT_FACTOR_TIME_MILLIS, EIGHT_FACTOR_ALLOCATION_BYTES, COLD_LANE
        ),
        "eightFactorAllSampleGatePass": gate(
            by_factor.get(8), EIGHT_FACTOR_TIME_MILLIS, EIGHT_FACTOR_ALLOCATION_BYTES, "allSample"
        ),
        "eightFactorSaturatedGatePass": gate(
            by_factor.get(8), EIGHT_FACTOR_TIME_MILLIS, EIGHT_FACTOR_ALLOCATION_BYTES, SATURATED_LANE
        ),
        "factors": records,
    }


def run_supervised(
    args: argparse.Namespace,
    repo_root: pathlib.Path,
    command: Sequence[str],
    result: pathlib.Path,
) -> int:
    result.parent.mkdir(parents=True, exist_ok=True)
    supervisor = [
        sys.executable,
        str((repo_root / "scripts/run-supervised-process.py").resolve()),
        "--timeout-seconds",
        str(args.timeout_seconds),
        "--termination-grace-seconds",
        str(args.termination_grace_seconds),
        "--status",
        str(status_path(result).resolve()),
        "--stdout",
        str(stdout_path(result).resolve()),
        "--stderr",
        str(stderr_path(result).resolve()),
        "--",
        *command,
    ]
    return subprocess.run(supervisor, cwd=repo_root, check=False).returncode


def audit_command(repo_root: pathlib.Path, jar: pathlib.Path, factor: int, result: pathlib.Path) -> list[str]:
    return [
        "java",
        "--class-path",
        str(jar.resolve()),
        str((repo_root / "scripts/PackedCascadesSearchStatusCli.java").resolve()),
        "--factors",
        str(factor),
        "--output",
        str(result.resolve()),
    ]


def jmh_command(
    args: argparse.Namespace,
    factor: int,
    result: pathlib.Path,
    *,
    warmup_iterations: int,
    measurement_iterations: int,
) -> list[str]:
    return [
        "java",
        "-jar",
        str(args.jar.resolve()),
        f"^{BENCHMARK}$",
        "-p",
        f"factors={factor}",
        "-wi",
        str(warmup_iterations),
        "-i",
        str(measurement_iterations),
        "-f",
        "1",
        "-t",
        "1",
        "-bm",
        "ss",
        "-tu",
        "ms",
        "-to",
        "60s",
        "-prof",
        "gc",
        "-rf",
        "json",
        "-rff",
        str(result.resolve()),
    ]


def write_index(args: argparse.Namespace, factors: Sequence[int]) -> None:
    cells = []
    for factor in factors:
        audit = audit_path(args.results, factor)
        cold = jmh_path(args.results, factor, COLD_LANE)
        saturated = jmh_path(args.results, factor, SATURATED_LANE)
        cells.append(
            {
                "factors": factor,
                "auditOutcome": outcome(audit) or "missing",
                "auditSha256": digest(audit),
                "auditStatusSha256": digest(status_path(audit)),
                "coldJmhOutcome": outcome(cold) or "missing",
                "coldJmhSha256": digest(cold),
                "coldJmhStatusSha256": digest(status_path(cold)),
                "saturatedJmhOutcome": outcome(saturated) or "missing",
                "saturatedJmhSha256": digest(saturated),
                "saturatedJmhStatusSha256": digest(status_path(saturated)),
            }
        )
    write_json(
        args.results / "campaign-index.json",
        {
            "formatVersion": 2,
            "jar": str(args.jar.resolve()),
            "jarSha256": digest(args.jar),
            "measurements": args.measurements,
            "saturatedWarmupIterations": args.warmup_iterations,
            "externalTimeoutSeconds": args.timeout_seconds,
            "factors": cells,
        },
    )


def persist(args: argparse.Namespace, factors: Sequence[int]) -> None:
    write_index(args, factors)
    write_json(
        args.summary,
        summarize_campaign(
            args.results,
            factors,
            args.measurements,
            args.warmup_iterations,
        ),
    )


def main() -> int:
    args = parse_args()
    repo_root = pathlib.Path(__file__).resolve().parents[1]
    factors = tuple(args.factor or FACTORS)
    args.results.mkdir(parents=True, exist_ok=True)
    persist(args, factors)
    for factor in factors:
        audit = audit_path(args.results, factor)
        if args.resume and completed_audit(audit, factor):
            print(f"[synthetic] retained factor {factor} audit", flush=True)
        else:
            print(f"[synthetic] running factor {factor} audit", flush=True)
            run_supervised(args, repo_root, audit_command(repo_root, args.jar, factor, audit), audit)
        persist(args, factors)
        if args.audit_only:
            continue
        cold = jmh_path(args.results, factor, COLD_LANE)
        if args.resume and jmh_entry(cold, factor, 0, 1) is not None:
            print(f"[synthetic] retained factor {factor} process-cold JMH", flush=True)
        else:
            print(f"[synthetic] running factor {factor} process-cold JMH", flush=True)
            run_supervised(
                args,
                repo_root,
                jmh_command(
                    args,
                    factor,
                    cold,
                    warmup_iterations=0,
                    measurement_iterations=1,
                ),
                cold,
            )
        persist(args, factors)
        saturated = jmh_path(args.results, factor, SATURATED_LANE)
        saturated_entry = jmh_entry(
            saturated,
            factor,
            args.warmup_iterations,
            args.measurements,
        )
        if args.resume and saturated_entry is not None:
            print(f"[synthetic] retained factor {factor} saturated JMH", flush=True)
        else:
            print(f"[synthetic] running factor {factor} saturated JMH", flush=True)
            run_supervised(
                args,
                repo_root,
                jmh_command(
                    args,
                    factor,
                    saturated,
                    warmup_iterations=args.warmup_iterations,
                    measurement_iterations=args.measurements,
                ),
                saturated,
            )
        persist(args, factors)
    summary = summarize_campaign(
        args.results,
        factors,
        args.measurements,
        args.warmup_iterations,
    )
    write_json(args.summary, summary)
    write_index(args, factors)
    return 0 if args.audit_only or summary["status"] == "complete" else 1


if __name__ == "__main__":
    sys.exit(main())
